    "chatbot.introInstructions": "மேலே உள்ள உங்கள் சுயவிவரத்தைத் தேர்ந்தெடுக்கவும், அதனால் நான் பதிலைத் தனிப்பயனாக்க முடியும். உங்கள் கேள்வியை ஆங்கிலத்தில் அல்லது உங்களுக்கு விருப்பமான பிராந்திய மொழியில் தட்டச்சு செய்யலாம் அல்லது பேசலாம்.",
