    "profiles.farmer.desc": "గ్రామీణ క్రెడిట్, లోన్ పేపర్‌వర్క్, రీపేమెంట్, ఇన్సూరెన్స్ మరియు సపోర్ట్ స్కీమ్‌లను సరళంగా అర్థం చేసుకోండి.",
    "profiles.student.desc": "విద్యార్థుల బ్యాంకింగ్, సేవింగ్స్ ఖాతాలు, విద్యా రుణాలు మరియు సురక్షితమైన డిజిటల్ చెల్లింపుల గురించి తెలుసుకోండి.",
    "profiles.msme.desc": "చిన్న-వ్యాపార క్రెడిట్, గ్రామీణ సంస్థలు, వర్కింగ్ క్యాపిటల్ మరియు అధికారిక బ్యాంకింగ్ దశలపై మార్గదర్శకత్వం పొందండి.",
    "profiles.salaried.desc": "రోజువారీ బ్యాంకింగ్, పొదుపులు, డిజిటల్ చెల్లింపులు మరియు మీ ఇంటి కోసం సురక్షితమైన రుణాల గురించి అడగండి.",
    "features.title": "మీకు కావలసిందల్లా",
    "features.langs.title": "13 భారతీయ భాషలు",
    "features.langs.desc": "చాట్, వాయిస్ మరియు కోర్ యాప్ టెక్స్ట్ కోసం మద్దతు ఉన్న భారతీయ భాషల మధ్య మారండి.",
    "features.voice.title": "వాయిస్ ఇన్‌పుట్",
    "features.voice.desc": "టైప్ చేయడం అసౌకర్యంగా ఉన్నప్పుడు మీ ప్రశ్నను మాట్లాడండి. అసిస్టెంట్ వాయిస్‌తో కూడా ప్రత్యుత్తరం ఇవ్వగలరు.",
    "features.guidance.title": "గ్రౌండెడ్ గైడెన్స్",
    "features.impact.title": "వ్యక్తిగతీకరించిన సమాధానాలు",
    "features.impact.desc": "మీ ప్రొఫైల్‌ని ఎంచుకోండి, తద్వారా జనమిత్ర మీ సందర్భానికి సరిపోయే విధంగా సమాధానాన్ని వివరించగలదు.",
    "features.fraud.title": "మోసం అవగాహన",
    "features.fraud.desc": "OTPలు, UPI, లోన్ యాప్‌లు మరియు అనుమానాస్పద కాల్‌ల కోసం ఆచరణాత్మక భద్రతా రిమైండర్‌లను పొందండి.",
    "works.subtitle": "సాధారణ ప్రక్రియ",
    "works.title": "జనమిత్ర ఎలా పనిచేస్తుంది",
    "works.desc": "డ్యాష్‌బోర్డ్ లేదా గణాంకాల స్క్రీన్ అవసరం లేకుండా, ప్రశ్న నుండి సమాధానం వరకు సెకన్లలో క్లియర్ అవుతుంది.",
    "works.step1.title": "మీ ప్రొఫైల్‌ను సెట్ చేయండి",
    "works.step1.desc": "మీరు రైతు, విద్యార్థి, ఎమ్‌ఎస్‌ఎమ్‌ఈ యజమాని, జీతం పొందే కార్మికుడు లేదా సాధారణ వినియోగదారు అయితే మాకు చెప్పండి.",
    "works.step2.title": "మీ ప్రశ్న అడగండి",
    "works.step4.title": "స్పష్టమైన సమాధానం పొందండి",
    "works.step4.desc": "ఆచరణాత్మక తదుపరి దశలతో సరళమైన వివరణను స్వీకరించండి.",
    "works.btn": "అడగడం ప్రారంభించండి",
    "fraud.subtitle": "రక్షణగా ఉండండి",
    "cta.btn1": "ఇప్పుడే చాటింగ్ ప్రారంభించండి",
    "cta.btn2": "చాట్‌బాట్ తెరవండి",
    "footer.disclaimer": "సమాచార సహాయకుడు, అధికారిక ఆర్థిక సలహా కాదు",
    "chatbot.introInstructions": "పైన ఉన్న మీ ప్రొఫైల్‌ని ఎంచుకోండి, తద్వారా నేను సమాధానాన్ని అనుకూలీకరించగలను. మీరు మీ ప్రశ్నను ఇంగ్లీష్ లేదా మీకు నచ్చిన ప్రాంతీయ భాషలో టైప్ చేయవచ్చు లేదా మాట్లాడవచ్చు.",
    "subTitle": "రైతులు & ఎమ్‌ఎస్‌ఎమ్‌ఈ యజమానులు గ్రామీణ బ్యాంకింగ్ అసిస్టెంట్",
    "settings.userProfileDesc": "మేము దీన్ని వ్యవసాయం, ఎమ్‌ఎస్‌ఎమ్‌ఈ వ్యాపారం, గ్రామీణ రుణాలు మరియు మీ పరిస్థితికి బ్యాంకింగ్ సమాధానాలను రూపొందించడానికి ఉపయోగిస్తాము.",
    "hero.sub": "రైతులు & ఎమ్‌ఎస్‌ఎమ్‌ఈ యజమానుల చాట్‌బాట్",
    "hero.title": "మీ భాషలో వ్యవసాయం, ఎమ్‌ఎస్‌ఎమ్‌ఈ & గ్రామీణ బ్యాంకింగ్ సహాయం పొందండి",
    "hero.desc": "పంట రుణాలు, కిసాన్ క్రెడిట్ కార్డ్ ప్రశ్నలు, గ్రామీణ బ్యాంకింగ్, సబ్సిడీలు, సురక్షితమైన డిజిటల్ చెల్లింపులు మరియు ఆచరణాత్మక వ్యవసాయం మరియు వ్యాపార మార్గదర్శకత్వం కోసం జనమిత్ర మిమ్మల్ని రైతులు & ఎమ్‌ఎస్‌ఎమ్‌ఈ ఓనర్‌ల చాట్‌బాట్‌కు కనెక్ట్ చేస్తుంది.",
    "alerts.title": "రైతు & ఎమ్‌ఎస్‌ఎమ్‌ఈ యజమాని సహాయ అంశాలు",
    "alerts.alert3": "పంట రుణాలు, ఎమ్‌ఎస్‌ఎమ్‌ఈ పథకాలు, సబ్సిడీ, బీమా మరియు వ్యవసాయ-క్రెడిట్ ప్రశ్నలు అడగడానికి మీ భాషను ఉపయోగించండి.",
    "profiles.subtitle": "గ్రామీణ & చిన్న వ్యాపార భారతదేశం కోసం రూపొందించబడింది",
    "profiles.desc": "రైతులు, ఎమ్‌ఎస్‌ఎమ్‌ఈ యజమానులు, విద్యార్థులు మరియు గృహస్థులు ఆచరణాత్మక ప్రశ్నలు అడగవచ్చు మరియు వారి ప్రొఫైల్‌కు ట్యూన్ చేయబడిన సాధారణ సమాధానాలను పొందవచ్చు.",
    "features.subtitle": "సహాయకరమైన రైతు & ఎమ్‌ఎస్‌ఎమ్‌ఈ యజమాని సాధనాలు",
