    "features.chat.desc": "వ్యవసాయ ఫైనాన్స్, ఎమ్‌ఎస్‌ఎమ్‌ఈ క్రెడిట్ మరియు గ్రామీణ బ్యాంకింగ్ ప్రశ్నలను సాధారణ ఆంగ్లంలో లేదా మీ స్థానిక భాషలో అడగండి.",
