    "works.step2.desc": "మీ వ్యవసాయం, ఎమ్‌ఎస్‌ఎమ్‌ఈ వ్యాపారం లేదా బ్యాంకింగ్ ప్రశ్నలను ఇంగ్లీష్ లేదా మీ ప్రాంతీయ భాషలో టైప్ చేయండి లేదా మాట్లాడండి.",
