    "cta.desc": "గ్రామీణ క్రెడిట్, KCC, ఎమ్‌ఎస్‌ఎమ్‌ఈ పథకాలు, సబ్సిడీలు, పంట రుణాలు, బీమా మరియు సురక్షితమైన డిజిటల్ బ్యాంకింగ్‌ను మీకు నచ్చిన భాషలో అర్థం చేసుకోవడానికి JanMitraని ఉపయోగించండి.",
