    "footer.disclaimerText": "సమాధానాలు రైతులు & ఎమ్‌ఎస్‌ఎమ్‌ఈ యజమానుల చాట్‌బాట్ సేవ నుండి అందించబడతాయి మరియు మీ బ్యాంక్ లేదా అధికారిక మూలాధారాలతో ధృవీకరణ అవసరం కావచ్చు.",
    "chatbot.introGreeting": "హలో! నేను జనమిత్ర, మీ రైతులు & ఎమ్‌ఎస్‌ఎమ్‌ఈ యజమానుల చాట్‌బాట్. నేను కిసాన్ క్రెడిట్ కార్డ్, పంట రుణాలు, ఎమ్‌ఎస్‌ఎమ్‌ఈ వ్యాపార పథకాలు, గ్రామీణ బ్యాంకింగ్, సబ్సిడీలు, బీమా, సురక్షితమైన UPI వినియోగం మరియు ఆచరణాత్మక వ్యవసాయం మరియు వ్యాపార ఆర్థిక ప్రశ్నలకు సహాయం చేయగలను.",
    "chatbot.thinking": "జనమిత్ర రైతులు & ఎమ్‌ఎస్‌ఎమ్‌ఈ యజమానుల చాట్‌బాట్ నాలెడ్జ్ బేస్‌ని తనిఖీ చేస్తోంది...",
    "chatbot.apiOffline": "API సర్వర్‌ని చేరుకోవడం సాధ్యపడలేదు. బ్యాకెండ్ పోర్ట్ 8080లో రన్ అవుతుందని మరియు రైతులు & ఎమ్‌ఎస్‌ఎమ్‌ఈ ఓనర్స్ చాట్‌బాట్ సర్వీస్ పోర్ట్ 8000లో రన్ అవుతుందని నిర్ధారించుకోండి."
