    "alerts.alert2": "സുരക്ഷിതമായ ഗ്രാമീണ ബാങ്കിംഗ്, യുപിഐ, ലോൺ ആപ്പുകൾ, വഞ്ചന തടയൽ എന്നിവയെക്കുറിച്ചുള്ള ലളിതമായ ഭാഷാ മാർഗനിർദേശം നേടുക.",
