    "profiles.msme.desc": "ചെറുകിട-ബിസിനസ് ക്രെഡിറ്റ്, ഗ്രാമീണ സംരംഭങ്ങൾ, പ്രവർത്തന മൂലധനം, ഔപചാരിക ബാങ്കിംഗ് ഘട്ടങ്ങൾ എന്നിവയിൽ മാർഗ്ഗനിർദ്ദേശം നേടുക.",
    "profiles.salaried.desc": "ദൈനംദിന ബാങ്കിംഗ്, സേവിംഗ്സ്, ഡിജിറ്റൽ പേയ്‌മെൻ്റുകൾ, നിങ്ങളുടെ വീട്ടുകാർക്ക് സുരക്ഷിതമായ കടം വാങ്ങൽ എന്നിവയെക്കുറിച്ച് ചോദിക്കൂ.",
    "features.title": "നിങ്ങൾക്ക് ആവശ്യമുള്ളതെല്ലാം",
