    "features.langs.desc": "ചാറ്റ്, വോയ്‌സ്, കോർ ആപ്പ് ടെക്‌സ്‌റ്റ് എന്നിവയ്‌ക്കായി പിന്തുണയ്‌ക്കുന്ന ഇന്ത്യൻ ഭാഷകൾക്കിടയിൽ മാറുക.",
