    "features.voice.desc": "ടൈപ്പ് ചെയ്യുന്നത് അസൗകര്യമുള്ളപ്പോൾ നിങ്ങളുടെ ചോദ്യം പറയുക. അസിസ്റ്റൻ്റിന് വോയ്‌സ് ഉപയോഗിച്ച് മറുപടി നൽകാനും കഴിയും.",
    "features.guidance.title": "അടിസ്ഥാനപരമായ മാർഗ്ഗനിർദ്ദേശം",
    "features.impact.title": "വ്യക്തിഗതമാക്കിയ ഉത്തരങ്ങൾ",
    "features.impact.desc": "നിങ്ങളുടെ പ്രൊഫൈൽ തിരഞ്ഞെടുക്കുക, അതുവഴി ജൻമിത്രയ്ക്ക് നിങ്ങളുടെ സന്ദർഭത്തിന് അനുയോജ്യമായ രീതിയിൽ ഉത്തരം വിശദീകരിക്കാനാകും.",
