    "settings.userProfileDesc": "અમે આનો ઉપયોગ ખેતી, એમએસએમઈ વ્યવસાય, ગ્રામીણ ધિરાણ અને તમારી પરિસ્થિતિના બેંકિંગ જવાબો તૈયાર કરવા માટે કરીએ છીએ.",
