    "hero.title": "તમારી ભાષામાં ખેતી, એમએસએમઈ અને ગ્રામીણ બેંકિંગ સહાય મેળવો",
    "hero.desc": "જનમિત્ર તમને પાક લોન, કિસાન ક્રેડિટ કાર્ડ પ્રશ્નો, ગ્રામીણ બેંકિંગ, સબસિડી, સુરક્ષિત ડિજિટલ ચૂકવણી અને વ્યવહારિક કૃષિ અને વ્યવસાય માર્ગદર્શન માટે ખેડૂતો અને એમએસએમઈ માલિકોના ચેટબોટ સાથે જોડે છે.",
    "alerts.title": "ખેડૂત અને એમએસએમઈ માલિક સહાય વિષયો",
    "alerts.alert3": "પાક-લોન, એમએસએમઈ યોજનાઓ, સબસિડી, વીમો અને કૃષિ-ધિરાણના પ્રશ્નો પૂછવા માટે તમારી ભાષાનો ઉપયોગ કરો.",
