    "profiles.desc": "ખેડૂતો, એમએસએમઈ માલિકો, વિદ્યાર્થીઓ અને પરિવારો વ્યવહારિક પ્રશ્નો પૂછી શકે છે અને તેમની પ્રોફાઇલ પર ટ્યુન કરેલા સરળ જવાબો મેળવી શકે છે.",
    "features.subtitle": "મદદરૂપ ખેડૂત અને એમએસએમઈ માલિક સાધનો",
    "features.chat.title": "ખેડૂતો અને એમએસએમઈ માલિકો ચેટબોટ",
    "features.chat.desc": "એગ્રીકલ્ચર ફાઇનાન્સ, એમએસએમઈ ક્રેડિટ અને ગ્રામીણ બેંકિંગના પ્રશ્નો સાદા અંગ્રેજી અથવા તમારી સ્થાનિક ભાષામાં પૂછો.",
    "features.guidance.desc": "જૂના પોલિસી ડેશબોર્ડને બદલે કનેક્ટેડ ખેડૂતો અને એમએસએમઈ માલિકોના ચેટબોટ તરફથી જવાબો આવે છે.",
    "works.step2.desc": "અંગ્રેજી અથવા તમારી પ્રાદેશિક ભાષામાં તમારી ખેતી, એમએસએમઈ વ્યવસાય અથવા બેંકિંગ પ્રશ્ન લખો અથવા બોલો.",
