    "works.step1.title": "ଆପଣଙ୍କର ପ୍ରୋଫାଇଲ୍ ସେଟ୍ କରନ୍ତୁ |",
    "works.step1.desc": "ଯଦି ଆପଣ ଜଣେ କୃଷକ, ଛାତ୍ର, ଏମ୍ଏସ୍ଏମ୍ଇ ମାଲିକ, ବେତନ ପ୍ରାପ୍ତ କର୍ମଚାରୀ କିମ୍ବା ସାଧାରଣ ବ୍ୟବହାରକାରୀ ତେବେ ଆମକୁ କୁହନ୍ତୁ |",
