    "cta.btn2": "ଚାଟବଟ୍ ଖୋଲନ୍ତୁ |",
    "footer.disclaimer": "ସୂଚନା ସହାୟକ ନୁହେଁ, ସରକାରୀ ଆର୍ଥିକ ପରାମର୍ଶ ନୁହେଁ |",
    "chatbot.introInstructions": "ଉପରେ ଆପଣଙ୍କର ପ୍ରୋଫାଇଲ୍ ଚୟନ କରନ୍ତୁ ଯାହା ଦ୍ I ାରା ମୁଁ ଉତ୍ତର କଷ୍ଟୋମାଇଜ୍ କରିପାରିବି | ତୁମେ ତୁମର ପ୍ରଶ୍ନକୁ ଇଂରାଜୀ କିମ୍ବା ତୁମର ପସନ୍ଦିତ ଆଞ୍ଚଳିକ ଭାଷାରେ ଟାଇପ୍ କିମ୍ବା କହିପାରିବ |",
    "subTitle": "କୃଷକ ଏବଂ ଏମ୍ଏସ୍ଏମ୍ଇ ମାଲିକ ଗ୍ରାମୀଣ ବ୍ୟାଙ୍କ ଆସିଷ୍ଟାଣ୍ଟ |",
    "settings.userProfileDesc": "ଚାଷ, ଏମଏସଏମଇ ବ୍ୟବସାୟ, ଗ୍ରାମୀଣ credit ଣ, ଏବଂ ଆପଣଙ୍କ ପରିସ୍ଥିତିର ବ୍ୟାଙ୍କିଙ୍ଗ ଉତ୍ତର ପାଇଁ ଆମେ ଏହାକୁ ବ୍ୟବହାର କରୁ |",
    "hero.sub": "କୃଷକ ଏବଂ ଏମ୍ଏସ୍ଏମ୍ଇ ମାଲିକ ଚାଟବଟ୍ |",
    "hero.title": "ଆପଣଙ୍କ ଭାଷାରେ ଚାଷ, ଏମ୍ଏସ୍ଏମ୍ଇ ଏବଂ ଗ୍ରାମୀଣ ବ୍ୟାଙ୍କିଂ ସହାୟତା ପ୍ରାପ୍ତ କରନ୍ତୁ |",
    "hero.desc": "ଜନମିତ୍ର ଆପଣଙ୍କୁ ଫସଲ loans ଣ, କିସାନ୍ କ୍ରେଡିଟ୍ କାର୍ଡ ଜିଜ୍ଞାସା, ଗ୍ରାମୀଣ ବ୍ୟାଙ୍କିଙ୍ଗ୍, ସବସିଡି, ନିରାପଦ ଡିଜିଟାଲ୍ ଦେୟ ଏବଂ ବ୍ୟବହାରିକ କୃଷି ଏବଂ ବ୍ୟବସାୟ ମାର୍ଗଦର୍ଶନ ପାଇଁ ଏକ କୃଷକ ଏବଂ ଏମ୍ଏସ୍ଏମ୍ଇ ମାଲିକ ଚାଟବଟ୍ ସହିତ ସଂଯୋଗ କରେ |",
    "alerts.title": "କୃଷକ ଏବଂ ଏମ୍ଏସ୍ଏମ୍ଇ ମାଲିକ ସହାୟତା ବିଷୟଗୁଡିକ |",
    "alerts.alert3": "ଫସଲ- loan ଣ, ଏମ୍ଏସ୍ଏମ୍ଇ ଯୋଜନା, ସବସିଡି, ବୀମା, ଏବଂ କୃଷି-କ୍ରେଡିଟ୍ ପ୍ରଶ୍ନ ପଚାରିବା ପାଇଁ ଆପଣଙ୍କର ଭାଷା ବ୍ୟବହାର କରନ୍ତୁ |",
    "profiles.subtitle": "ଗ୍ରାମୀଣ ଏବଂ କ୍ଷୁଦ୍ର ବ୍ୟବସାୟ ଭାରତ ପାଇଁ ପ୍ରସ୍ତୁତ |",
    "profiles.desc": "କୃଷକ, ଏମଏସଏମଇ ମାଲିକ, ଛାତ୍ର, ଏବଂ ପରିବାର ବ୍ୟବହାରିକ ପ୍ରଶ୍ନ ପଚାରିପାରିବେ ଏବଂ ସେମାନଙ୍କ ପ୍ରୋଫାଇଲରେ ସରଳ ଉତ୍ତର ଗ୍ରହଣ କରିପାରିବେ |",
    "features.subtitle": "ସହାୟକ କୃଷକ ଏବଂ ଏମ୍ଏସ୍ଏମ୍ଇ ମାଲିକ ଉପକରଣଗୁଡିକ |",
