    "features.chat.desc": "ସାଧା ଇଂରାଜୀ କିମ୍ବା ଆପଣଙ୍କ ସ୍ଥାନୀୟ ଭାଷାରେ କୃଷି ଅର୍ଥ, ଏମ୍ଏସ୍ଏମ୍ଇ କ୍ରେଡିଟ୍ ଏବଂ ଗ୍ରାମୀଣ ବ୍ୟାଙ୍କିଙ୍ଗ୍ ପ୍ରଶ୍ନ ପଚାର |",
    "features.guidance.desc": "ପୁରୁଣା ନୀତି ଡ୍ୟାସବୋର୍ଡ ପରିବର୍ତ୍ତେ ସଂଯୁକ୍ତ କୃଷକ ଏବଂ ଏମ୍ଏସ୍ଏମ୍ଇ ମାଲିକ ଚାଟବଟରୁ ଉତ୍ତର ଆସେ |",
