    "works.step3.title": "ଚାଟବଟ୍ ପ୍ରସଙ୍ଗ ଖୋଜେ |",
    "works.step3.desc": "ଗ୍ରାଉଣ୍ଡ୍ ପୁନରୁଦ୍ଧାର ପାଇଁ ବ୍ୟାକେଣ୍ଡ୍ ଆପଣଙ୍କ ପ୍ରଶ୍ନ କୃଷକ ଏବଂ ଏମ୍ଏସ୍ଏମ୍ଇ ମାଲିକ ଚାଟବଟ୍ ସେବାକୁ ପଠାଏ |",
    "fraud.title": "ଗ୍ରାମୀଣ ଏବଂ ବ୍ୟବସାୟ ବ୍ୟାଙ୍କିଙ୍ଗ ସୁରକ୍ଷା |",
    "cta.badge": "କୃଷକ ଏବଂ ଏମ୍ଏସ୍ଏମ୍ଇ ମାଲିକ ଚାଟବଟ୍ ଦ୍ୱାରା ଚାଳିତ |",
    "cta.title": "ଚାଷ, ଏମଏସଏମଇ ଏବଂ ବ୍ୟାଙ୍କିଙ୍ଗ ପ୍ରଶ୍ନକୁ ସ୍ପଷ୍ଟ ଭାବରେ ପଚାର |",
    "cta.desc": "ଗ୍ରାମୀଣ credit ଣ, କେସିସି, ଏମଏସଏମଇ ଯୋଜନା, ସବସିଡି, ଫସଲ loans ଣ, ବୀମା ଏବଂ ସୁରକ୍ଷିତ ଡିଜିଟାଲ ବ୍ୟାଙ୍କିଙ୍ଗକୁ ଆପଣଙ୍କ ପସନ୍ଦିତ ଭାଷାରେ ବୁ to ିବା ପାଇଁ ଜନମିତ୍ର ବ୍ୟବହାର କରନ୍ତୁ |",
    "footer.subtitle": "କୃଷକ ଏବଂ ଏମଏସଏମଇ ମାଲିକମାନଙ୍କୁ ଆର୍ଥିକ ମାର୍ଗଦର୍ଶନ କରିବାରେ ସାହାଯ୍ୟ କରିବା |",
    "footer.disclaimerText": "ଉତ୍ତରଗୁଡିକ କୃଷକ ଏବଂ ଏମ୍ଏସ୍ଏମ୍ଇ ମାଲିକ ଚାଟବଟ୍ ସେବା ଠାରୁ ଆସିଥାଏ ଏବଂ ଆପଣଙ୍କ ବ୍ୟାଙ୍କ କିମ୍ବା ଅଫିସିଆଲ୍ ଉତ୍ସ ସହିତ ଯାଞ୍ଚ ଆବଶ୍ୟକ ହୋଇପାରେ |",
