// Simple Fallback Translator
export function getTranslation(lang: string, keyPath: string): string {
  const normalizedLang = lang.toLowerCase();
  if (farmerOverrides[normalizedLang] && farmerOverrides[normalizedLang][keyPath]) {
    return farmerOverrides[normalizedLang][keyPath];
  }
  if (farmerOverrides.english && farmerOverrides.english[keyPath]) {
    return farmerOverrides.english[keyPath];
  }

  const keys = keyPath.split(".");
  let current = translations[lang] || translations.english;
  for (const key of keys) {
    if (current && current[key] !== undefined) {
      current = current[key];
    } else {
      // Fallback to English
      let englishFallback = translations.english;
      for (const k of keys) {
        englishFallback = englishFallback ? englishFallback[k] : undefined;
      }
      return (englishFallback as any) || keyPath;
    }
  }
  return current as any;
}
